    reply.begin(_a)
    reply.note(_a, "ok_intent", True, "已做")
    reply.note(_a, "bad_intent", False, "没做")
    _rep2 = reply.flush(_a)
    ok("总返回聚合（成功/失败计数）",
       bool(_rep2) and _rep2["executed"] == 1 and _rep2["failed"] == 1
       and _rep2["ok"] is False, _rep2["text"][:60] if _rep2 else "None")
    ok("last_reply 已挂到 agent",
       getattr(_a, "last_reply", None) is not None)

    # 12 听写: 终端在【on 模式】算"可输入"（auto 模式不算，见 #14）
    import typein as _ti
    _cls_bak, _focus_bak = _ti._class_of, _ti._focus_class_now
    _mode_bak0 = _ti.get_mode()
    try:
        _ti.set_mode("on")
        _ti._class_of = lambda h: "ConsoleWindowClass"
        _ti._focus_class_now = lambda: ""
        _ist = _ti.caret_state()
        _okf, _why = _ti.in_text_field()
        ok("终端（开始输入后）被认成可输入", bool(_ist.get("is_terminal")) and _okf is True,
           _why[:40])
        _ti._class_of = lambda h: "CASCADIA_HOSTING_WINDOW_CLASS"
        ok("Windows Terminal 被认成可输入", _ti.in_text_field()[0] is True)
        # 但"清空输入"在终端里必须拒（Ctrl+A/Delete 在 shell 里是别的东西）
        _cs, _cf = _ti.caret_state, _ti.in_text_field
        _ti.caret_state = lambda: {"is_terminal": True, "focus_class": "ConsoleWindowClass",
                                   "has_caret": False, "looks_edit": False,
                                   "in_text_field": True}
        ok("终端里拒绝清空输入", _ti.clear_field(dry=True)[0] is False)
        _ti.caret_state = _cs
    finally:
        _ti._class_of, _ti._focus_class_now = _cls_bak, _focus_bak
        _ti.caret_state = locals().get("_cs", _ti.caret_state)
